```swift
import Foundation

struct User {
    var clicks: [String]
    var colorPreferences: [String]
    var productReviews: [String]
}

func generateStatement(for user: User) -> String {
    var statement = ""

    // Add click-based statement
    if !user.clicks.isEmpty {
        statement += "Based on your clicks, we recommend the following products:"
        statement += "\n"
        for click in user.clicks {
            statement += "- \(click)\n"
        }
    }

    // Add color preference-based statement
    if !user.colorPreferences.isEmpty {
        statement += "Since you prefer \(user.colorPreferences.joined(separator: ", ")), we suggest the following products:"
        statement += "\n"
        for product in user.productReviews.filter { $0.contains(user.colorPreferences.joined(separator: ", ")) } {
            statement += "- \(product)\n"
        }
    }

    // Add product review-based statement
    if !user.productReviews.isEmpty {
        statement += "Based on your positive reviews of the following products, we recommend the following similar products:"
        statement += "\n"
        for product in user.productReviews.filter { $0.contains("positive") } {
            statement += "- \(product)\n"
        }
    }

    return statement
}

