2. Create a JavaScript file named "script.js" and add the following code:

```javascript
const primeNumbers = [3, 7, 13, 19];
const productElement = document.getElementById("product");
const calculateProductButton = document.getElementById("calculate-product");
const primeNumbersList = document.getElementById("prime-numbers");

function displayPrimeNumbers() {
    primeNumbersList.innerHTML = "";
    primeNumbers.forEach(primeNumber => {
        const listItem = document.createElement("li");
        listItem.textContent = primeNumber;
        primeNumbersList.appendChild(listItem);
    });
}

function calculateProduct() {
    const product = primeNumbers.reduce((accumulator, currentValue) => accumulator * currentValue);
    productElement.textContent = `The product of ${primeNumbers.join(", ")} is ${product}.`;
}

displayPrimeNumbers();
calculateProductButton.addEventListener("click", calculateProduct);
```

This code creates an unordered list (`<ul>`) to display the prime numbers and a button to calculate their product. When the button is clicked, the product is calculated using the `reduce()` method and displayed on the page.

