```javascript
function sortAsc(arr) {
  arr.sort((a, b) => a - b);
  return arr;
}

const inputArray = [3, 7, 2, 1, 6];
const sortedArray = sortAsc(inputArray);
console.log(sortedArray); // Output: [1, 2, 3, 6, 7]
