Here's the `redis.js` file with the `RedisClient` class and an instance of it named `redisClient`:

```javascript
const { Redis } = require("ioredis");

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: "localhost",
      port: 6379,
      db: 0,
    });

    this.client.on("error", (err) => {
      console.error("Redis Error:", err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      throw new Error(`Error getting value from Redis: ${err}`);
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
      return true;
    } catch (err) {
      throw new Error(`Error setting value in Redis: ${err}`);
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
      return true;
    } catch (err) {
      throw new Error(`Error deleting value from Redis: ${err}`);
    }
  }
}

const redisClient = new RedisClient();

module.exports = { redisClient };
```

